const item = $input.first();

const output = [];

const supportedMimeTypes = [
  'application/pdf',
  'image/jpeg',
  'image/png',
  'image/heic',
  'image/heif'
];

const supportedExtensions = [
  '.pdf',
  '.jpg',
  '.jpeg',
  '.png',
  '.heic',
  '.heif'
];

for (const key of Object.keys(item.binary || {})) {
  const attachment = item.binary[key];

  const fileName = String(attachment.fileName || '').toLowerCase();
  const mimeType = String(attachment.mimeType || '').toLowerCase();

  const extensionSupported = supportedExtensions.some(ext =>
    fileName.endsWith(ext)
  );

  const mimeTypeSupported = supportedMimeTypes.includes(mimeType);

  // Accept the attachment if either:
  // 1. Its MIME type is supported, OR
  // 2. Its file extension is supported
  if (mimeTypeSupported || extensionSupported) {
    output.push({
      json: {
        attachment_field: key,
        file_name: attachment.fileName,
        mime_type: attachment.mimeType
      },
      binary: {
        data: attachment
      }
    });
  }
}

return output;

const binaryData = $input.item.binary.data;

// Get the actual binary buffer for the current item
const buffer = await this.helpers.getBinaryDataBuffer($itemIndex, 'data');

const mimeType = binaryData.mimeType;
const base64 = buffer.toString('base64');

return {
  json: {
    file_name: binaryData.fileName,
    mime_type: mimeType,
    image_data_url: `data:${mimeType};base64,${base64}`
  },
  binary: {
    data: binaryData
  }
};

const items = $input.all();

const output = [];

for (const item of items) {
  const content = item.json?.choices?.[0]?.message?.content;

  if (!content) {
    output.push({
      json: {
        extraction_valid: false,
        extraction_status: "REVIEW_REQUIRED",
        extraction_issues: ["No AI response content found"],
        raw_response: item.json
      },
      binary: item.binary
    });

    continue;
  }

  try {
    // Remove Markdown code fences if the AI adds them
    let cleaned = content
      .replace(/```json/gi, "")
      .replace(/```/g, "")
      .trim();

    // Convert the AI response into JSON
    const parsed = JSON.parse(cleaned);
    parsed.extraction_pass = item.json?.retry_count
     ? "RETRY"
     : "INITIAL";

    // Remove TOTAL AMOUNT entries from line_items.
    // Total amounts belong in amount_breakdown, not line_items.
    if (Array.isArray(parsed.line_items)) {
      parsed.line_items = parsed.line_items.filter((line) => {
        const name = String(line?.item_name || "").toUpperCase().trim();

        return !(
          name === "TOTAL AMOUNT" ||
          name === "TOTAL AMOUNT DUE" ||
          name === "GRAND TOTAL" ||
          name === "TOTAL"
        );
      });
    }

    // Preserve the original image information from Prepare Image for AI.
    const preservedData = {};

    if (item.json?.file_name) {
      preservedData.file_name = item.json.file_name;
    }

    if (item.json?.mime_type) {
      preservedData.mime_type = item.json.mime_type;
    }

    if (item.json?.image_data_url) {
      preservedData.image_data_url = item.json.image_data_url;
    }

    if (item.json?.retry_count !== undefined) {
       preservedData.retry_count = item.json.retry_count;
    }

    output.push({
      json: {
        ...parsed,
        ...preservedData
      },
      binary: item.binary
    });

  } catch (error) {
    output.push({
      json: {
        extraction_valid: false,
        extraction_status: "REVIEW_REQUIRED",
        extraction_issues: [
          "AI response could not be parsed as valid JSON"
        ],
        parse_error: error.message,
        raw_ai_response: content,

        file_name: item.json?.file_name || null,
        mime_type: item.json?.mime_type || null,
        image_data_url: item.json?.image_data_url || null
      },
      binary: item.binary
    });
  }
}

return output;

const items = $input.all();

return items.map((item, index) => {
  const binary = item.binary?.data;

  if (!binary) {
    throw new Error("No binary data found in field 'data'.");
  }

  // Get the original filename from the HEIF routing node
  const originalBinary =
    $('Route by File Type').all()[index]?.binary?.data;

  const originalFileName =
    originalBinary?.fileName || "converted-image.heif";

  // Remove HEIC/HEIF extension and add JPG
  const convertedFileName =
    originalFileName.replace(
      /\.(heic|heif)$/i,
      ""
    ) + ".jpg";

  return {
    json: {
      original_file_name: originalFileName,
      converted_file_name: convertedFileName,
      converted_mime_type: "image/jpeg"
    },

    binary: {
      data: {
        ...binary,
        fileName: convertedFileName,
        fileExtension: "jpg",
        mimeType: "image/jpeg"
      }
    }
  };
});

const items = $input.all();

function normalizeText(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

function normalizeInvoiceNumber(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "")
    .replace(/–/g, "-")
    .replace(/—/g, "-");
}

function normalizeDate(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

function normalizeAmount(value) {
  const number = Number(value);

  if (!Number.isFinite(number)) {
    return "";
  }

  return number.toFixed(2);
}

return items.map(item => {
  const invoice = item.json;

  const vendor = normalizeText(
    invoice.vendor
  );

  const invoiceNumber = normalizeInvoiceNumber(
    invoice.invoice_number
  );

  const invoiceDate = normalizeDate(
    invoice.invoice_date
  );

  const currency = normalizeText(
    invoice.currency
  );

  const totalAmount = normalizeAmount(
    invoice.total_amount
  );

  const fingerprintSource = [
    vendor,
    invoiceNumber,
    invoiceDate,
    currency,
    totalAmount
  ].join("|");

  return {
    json: {
      ...invoice,
      invoice_fingerprint: fingerprintSource
    }
  };
});

const item = $input.first();
const invoice = item.json;

return [
  {
    json: {
      ...invoice,
      retry_count: (invoice.retry_count || 0) + 1,
      retry_required: true,
      retry_reason: "Merged financial lines detected",
      retry_instruction:
        "Re-read the entire document image carefully. Do not combine separate printed lines. Preserve every visible financial line as its own amount_breakdown entry and its own line_item when applicable. Pay particular attention to document numbers and distinguish the main document number from SOA numbers, reference numbers, and other identifiers. If a value is unclear, return null rather than guessing."
    }
  }
];

const aiItem = $input.first();
const retrySource = $('Prepare Re-Extraction').item;

return [
  {
    json: {
      ...aiItem.json,

      retry_count: retrySource.json.retry_count ?? 0,
      file_name: retrySource.json.file_name ?? null,
      mime_type: retrySource.json.mime_type ?? null,
      image_data_url: retrySource.json.image_data_url ?? null
    },
    binary: retrySource.binary ?? aiItem.binary
  }
];

const items = $input.all();
const output = [];

// ============================================================
// HELPER FUNCTIONS
// ============================================================

function num(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function round2(value) {
  return Number(Number(value).toFixed(2));
}

function text(value) {
  return String(value ?? "").trim();
}

function upper(value) {
  return text(value).toUpperCase();
}

function entryLabel(entry) {
  return upper(entry?.label ?? entry?.description ?? "");
}

function entryType(entry) {
  return upper(entry?.type ?? "");
}

function isApproximatelyEqual(a, b) {
  if (a === null || b === null) return false;
  return Math.abs(a - b) < 0.01;
}

// ============================================================
// PROCESS EACH INVOICE
// ============================================================

for (const item of items) {

  const invoice = item.json || {};
  const problems = [];

  // ============================================================
  // BASIC DOCUMENT VALIDATION
  // ============================================================

  if (!invoice.vendor) {
    problems.push("Missing vendor");
  }

  if (!invoice.invoice_number) {
    problems.push("Missing invoice number");
  }

  if (!invoice.invoice_date) {
    problems.push("Missing invoice date");
  }

  // ============================================================
  // CURRENCY NORMALIZATION
  // ============================================================

  let normalizedCurrency = text(invoice.currency);

  if (!normalizedCurrency) {
    normalizedCurrency = "USD";
  }

  // ============================================================
  // LINE ITEMS
  // ============================================================

  if (
    !Array.isArray(invoice.line_items) ||
    invoice.line_items.length === 0
  ) {
    problems.push("No line items extracted");
  }

  // ============================================================
  // AMOUNT BREAKDOWN
  // ============================================================

  const breakdown = Array.isArray(invoice.amount_breakdown)
    ? invoice.amount_breakdown
    : [];

  // ============================================================
  // FIND SUBTOTAL
  // ============================================================

  const subtotalEntries = breakdown.filter(entry => {

    const label = entryLabel(entry);
    const type = entryType(entry);

    return (
      type === "SUBTOTAL" ||
      label === "SUBTOTAL" ||
      label === "NET SALES" ||
      label === "NET SALE" ||
      label === "NET AMOUNT" ||
      label === "VATABLE SALES" ||
      label === "VATABLE SALE" ||
      label === "TAXABLE SALES" ||
      label === "TAXABLE SALE"
    );
  });

  let extractedSubtotal = null;

  if (subtotalEntries.length > 0) {

    const firstSubtotal = subtotalEntries[0];
    const amount = num(firstSubtotal?.amount);

    if (amount !== null) {
      extractedSubtotal = amount;
    }
  }

  // ============================================================
  // FIND SUBTOTAL AFTER DISCOUNT
  // ============================================================

  const subtotalAfterDiscountEntry = breakdown.find(entry => {

    const label = entryLabel(entry);

    return (
      label.includes("SUBTOTAL AFTER DISCOUNT") ||
      label.includes("SUBTOTAL AFTER DEDUCTION") ||
      label.includes("NET AFTER DISCOUNT") ||
      label.includes("NET AFTER DEDUCTION")
    );
  });

  let extractedSubtotalAfterDiscount = null;

  if (subtotalAfterDiscountEntry) {

    const amount = num(subtotalAfterDiscountEntry.amount);

    if (amount !== null) {
      extractedSubtotalAfterDiscount = amount;
    }
  }

  // ============================================================
  // FIND TOTAL
  // ============================================================

  const totalEntry = breakdown.find(entry => {

    const label = entryLabel(entry);
    const type = entryType(entry);

    return (
      type === "TOTAL" ||
      label === "TOTAL" ||
      label === "TOTAL AMOUNT" ||
      label === "TOTAL AMOUNT DUE" ||
      label === "GRAND TOTAL" ||
      label === "INVOICE TOTAL" ||
      label === "TOTAL DUE"
    );
  });

  let extractedTotal = null;

  if (totalEntry) {

    const amount = num(totalEntry?.amount);

    if (amount !== null) {
      extractedTotal = amount;
    }
  }

  if (
    extractedTotal === null &&
    invoice.total_amount !== null &&
    invoice.total_amount !== undefined
  ) {
    extractedTotal = num(invoice.total_amount);
  }

  // ============================================================
  // FIND AMOUNT DUE
  // ============================================================

  const amountDueEntry = breakdown.find(entry => {

    const label = entryLabel(entry);

    return (
      label === "AMOUNT DUE" ||
      label === "BALANCE DUE" ||
      label === "TOTAL DUE" ||
      label === "BALANCE PAYABLE" ||
      label === "AMOUNT PAYABLE" ||
      label.includes("AMOUNT DUE") ||
      label.includes("BALANCE DUE")
    );
  });

  let extractedAmountDue = null;

  if (amountDueEntry) {

    const amount = num(amountDueEntry?.amount);

    if (amount !== null) {
      extractedAmountDue = amount;
    }
  }

  if (
    extractedAmountDue === null &&
    invoice.amount_due !== null &&
    invoice.amount_due !== undefined
  ) {
    extractedAmountDue = num(invoice.amount_due);
  }

  // ============================================================
  // FIND PAYMENT RECEIVED
  // ============================================================

  const paymentEntries = breakdown.filter(entry => {

    const label = entryLabel(entry);
    const type = entryType(entry);

    return (
      type === "PAYMENT" ||
      label === "PAYMENT RECEIVED" ||
      label === "AMOUNT PAID" ||
      label === "PAID" ||
      label.includes("PAYMENT RECEIVED") ||
      label.includes("PAYMENT MADE") ||
      label.includes("PAYMENTS RECEIVED")
    );
  });

  let extractedPaymentReceived = 0;

  if (paymentEntries.length > 0) {

    extractedPaymentReceived = paymentEntries.reduce(
      (sum, entry) => {

        const amount = num(entry?.amount);

        if (amount === null) {
          return sum;
        }

        return sum + Math.abs(amount);
      },
      0
    );
  }

  if (
    paymentEntries.length === 0 &&
    invoice.payment_received !== null &&
    invoice.payment_received !== undefined
  ) {

    const directPayment = num(invoice.payment_received);

    if (directPayment !== null) {
      extractedPaymentReceived = Math.abs(directPayment);
    }
  }

  extractedPaymentReceived = round2(extractedPaymentReceived);

  // ============================================================
  // CALCULATE LINE ITEM TOTAL
  // ============================================================

  let calculatedLineItemsTotal = null;

  if (
    Array.isArray(invoice.line_items) &&
    invoice.line_items.length > 0
  ) {

    let validLineItems = true;

    const lineTotal = invoice.line_items.reduce(
      (sum, line) => {

        const total = num(line?.total);

        if (total === null) {
          validLineItems = false;
          return sum;
        }

        return sum + total;
      },
      0
    );

    if (validLineItems) {
      calculatedLineItemsTotal = round2(lineTotal);
    }
  }

  // ============================================================
  // DETERMINE CALCULATION BASE
  // ============================================================

  let calculationBaseSubtotal = null;

  if (calculatedLineItemsTotal !== null) {
    calculationBaseSubtotal = calculatedLineItemsTotal;
  } else if (extractedSubtotal !== null) {
    calculationBaseSubtotal = extractedSubtotal;
  }

  // ============================================================
  // LINE ITEMS VS SUBTOTAL
  // ============================================================

  let lineItemsMatchSubtotal = null;

  if (
    calculatedLineItemsTotal !== null &&
    extractedSubtotal !== null
  ) {

    lineItemsMatchSubtotal =
      isApproximatelyEqual(
        calculatedLineItemsTotal,
        extractedSubtotal
      );

    if (!lineItemsMatchSubtotal) {

      problems.push(
        `Calculated line items total ${calculatedLineItemsTotal.toFixed(2)} does not match extracted subtotal ${extractedSubtotal.toFixed(2)}`
      );
    }
  }

  // ============================================================
  // TAX DETECTION
  // ============================================================

  const taxEntries = breakdown.filter(entry => {

    const label = entryLabel(entry);
    const type = entryType(entry);

    return (
      type === "TAX" ||
      label === "VAT" ||
      label.includes("VALUE ADDED TAX") ||
      label.includes("SALES TAX") ||
      label.includes("STATE TAX") ||
      label.includes("CITY TAX") ||
      label.includes("COUNTY TAX") ||
      label.includes("LOCAL GOVT") ||
      label.includes("LOCAL GOVERNMENT") ||
      label.includes("GST") ||
      label.includes("HST") ||
      label.includes("PST") ||
      label.includes("QST") ||
      label.includes("TAX (")
    );
  });

  let extractedTax = null;

  if (taxEntries.length > 0) {

    extractedTax = round2(
      taxEntries.reduce(
        (sum, entry) => {

          const amount = num(entry?.amount);

          if (amount === null) {
            return sum;
          }

          return sum + Math.abs(amount);
        },
        0
      )
    );
  }

  if (
    extractedTax === null &&
    invoice.tax !== null &&
    invoice.tax !== undefined
  ) {

    const directTax = num(invoice.tax);

    if (directTax !== null) {
      extractedTax = Math.abs(directTax);
    }
  }

  // ============================================================
  // TAX RATE DETECTION
  // ============================================================

  let extractedTaxRate = null;

  for (const entry of taxEntries) {

    const label = entryLabel(entry);

    const rateMatch =
      label.match(/(\d+(?:\.\d+)?)\s*%/);

    if (rateMatch) {

      const rate = num(rateMatch[1]);

      if (
        rate !== null &&
        rate >= 0 &&
        rate <= 100
      ) {
        extractedTaxRate = rate;
        break;
      }
    }
  }

  // ============================================================
  // DISCOUNT DETECTION
  // ============================================================

  const discountEntries = breakdown.filter(entry => {

    const label = entryLabel(entry);
    const type = entryType(entry);

    const isSubtotalAfterDiscount =
      label.includes("SUBTOTAL AFTER DISCOUNT") ||
      label.includes("SUBTOTAL AFTER DEDUCTION") ||
      label.includes("NET AFTER DISCOUNT") ||
      label.includes("NET AFTER DEDUCTION");

    if (isSubtotalAfterDiscount) {
      return false;
    }

    return (
      type === "DISCOUNT" ||
      label === "DISCOUNT" ||
      label.startsWith("DISCOUNT ") ||
      label.includes(" REBATE") ||
      label.startsWith("REBATE") ||
      label.includes(" PROMO") ||
      label.startsWith("PROMO") ||
      label.includes("PROMOTIONAL")
    );
  });

  let discountPresent = discountEntries.length > 0;
  let discountAmount = 0;
  let discountAmountSource = "none";

  // ============================================================
  // EXTRACT DISCOUNT PERCENTAGE
  // ============================================================

  let discountRate = null;

  for (const entry of discountEntries) {

    const label = entryLabel(entry);

    const percentMatch = label.match(
      /(\d+(?:\.\d+)?)\s*%/
    );

    if (percentMatch) {

      const parsedRate = Number(percentMatch[1]);

      if (
        Number.isFinite(parsedRate) &&
        parsedRate >= 0 &&
        parsedRate <= 100
      ) {
        discountRate = parsedRate;
        break;
      }
    }
  }

  // ============================================================
  // DERIVE DISCOUNT FROM AUTHORITATIVE CALCULATION BASE
  // ============================================================

  let derivedDiscountAmount = null;

  if (
    discountRate !== null &&
    calculationBaseSubtotal !== null
  ) {

    derivedDiscountAmount =
      round2(
        calculationBaseSubtotal *
        (discountRate / 100)
      );
  }

  // ============================================================
  // DERIVE DISCOUNT FROM SUBTOTALS WHEN NO PERCENTAGE EXISTS
  // ============================================================

  if (
    derivedDiscountAmount === null &&
    calculationBaseSubtotal !== null &&
    extractedSubtotalAfterDiscount !== null
  ) {

    const difference =
      calculationBaseSubtotal -
      extractedSubtotalAfterDiscount;

    if (difference >= 0) {

      derivedDiscountAmount =
        round2(difference);
    }
  }

  // ============================================================
  // EXPLICIT DISCOUNT AMOUNT
  // ============================================================

  let explicitDiscountAmount = null;

  if (discountEntries.length > 0) {

    explicitDiscountAmount =
      round2(
        discountEntries.reduce(
          (sum, entry) => {

            const amount = num(entry?.amount);

            if (amount === null) {
              return sum;
            }

            return sum + Math.abs(amount);
          },
          0
        )
      );
  }

  // ============================================================
  // DISCOUNT RECONCILIATION
  // ============================================================

  if (
    discountRate !== null &&
    derivedDiscountAmount !== null
  ) {

    discountAmount =
      derivedDiscountAmount;

    if (
      explicitDiscountAmount !== null &&
      isApproximatelyEqual(
        explicitDiscountAmount,
        derivedDiscountAmount
      )
    ) {

      discountAmountSource =
        "reconciled_percentage_and_explicit";

    } else {

      discountAmountSource =
        "calculated_from_percentage";
    }

  } else if (
    derivedDiscountAmount !== null
  ) {

    discountAmount =
      derivedDiscountAmount;

    if (explicitDiscountAmount !== null) {

      discountAmountSource =
        "derived_due_to_explicit_discount_mismatch";

    } else {

      discountAmountSource =
        "derived_from_authoritative_subtotal";
    }

  } else if (
    explicitDiscountAmount !== null
  ) {

    discountAmount =
      explicitDiscountAmount;

    discountAmountSource =
      "explicit_discount_entry";
  }

  discountAmount = round2(discountAmount);

  // ============================================================
  // CALCULATE SUBTOTAL AFTER DISCOUNT
  // ============================================================

  let calculatedSubtotalAfterDiscount = null;

  if (calculationBaseSubtotal !== null) {

    calculatedSubtotalAfterDiscount =
      round2(
        calculationBaseSubtotal -
        discountAmount
      );
  }

  // ============================================================
  // VALIDATE SUBTOTAL AFTER DISCOUNT
  // ============================================================

  let subtotalAfterDiscountReconciled = null;

  if (
    calculatedSubtotalAfterDiscount !== null &&
    extractedSubtotalAfterDiscount !== null
  ) {

    subtotalAfterDiscountReconciled =
      isApproximatelyEqual(
        calculatedSubtotalAfterDiscount,
        extractedSubtotalAfterDiscount
      );

    if (!subtotalAfterDiscountReconciled) {

      problems.push(
        `Calculated subtotal after discount ${calculatedSubtotalAfterDiscount.toFixed(2)} does not match extracted subtotal after discount ${extractedSubtotalAfterDiscount.toFixed(2)}`
      );
    }
  }

  // ============================================================
  // ADDITIONAL CHARGES / FEES
  // ============================================================

  const chargeEntries = breakdown.filter(entry => {

    const type = entryType(entry);
    const label = entryLabel(entry);

    if (
      type === "SUBTOTAL" ||
      type === "TAX" ||
      type === "DISCOUNT" ||
      type === "TOTAL" ||
      type === "PAYMENT"
    ) {
      return false;
    }

    if (
      label.includes("SUBTOTAL") ||
      label.includes("DISCOUNT") ||
      label.includes("REBATE") ||
      label.includes("PROMO") ||
      label === "TOTAL" ||
      label.includes("TOTAL AMOUNT") ||
      label.includes("GRAND TOTAL") ||
      label.includes("INVOICE TOTAL") ||
      label.includes("AMOUNT DUE") ||
      label.includes("BALANCE DUE") ||
      label.includes("TOTAL DUE") ||
      label.includes("PAYMENT RECEIVED") ||
      label.includes("AMOUNT PAID") ||
      label === "PAID"
    ) {
      return false;
    }

    if (
      type === "FEE" ||
      type === "CHARGE" ||
      type === "SURCHARGE"
    ) {
      return true;
    }

    return (
      label.includes("FEE") ||
      label.includes("SURCHARGE") ||
      label.includes("PROCESSING") ||
      label.includes("HANDLING") ||
      label.includes("SHIPPING") ||
      label.includes("ADMINISTRATIVE") ||
      label.includes("CONVENIENCE") ||
      label.includes("DISPOSAL") ||
      label.includes("ENVIRONMENTAL") ||
      label.includes("SERVICE CHARGE") ||
      label.includes("OTHER CHARGE")
    );
  });

  let additionalCharges = 0;

  if (chargeEntries.length > 0) {

    additionalCharges = round2(
      chargeEntries.reduce(
        (sum, entry) => {

          const amount = num(entry?.amount);

          if (amount === null) {
            return sum;
          }

          return sum + Math.abs(amount);
        },
        0
      )
    );
  }

  // ============================================================
  // TAX CALCULATION
  //
  // IMPORTANT:
  //
  // Tax is calculated AFTER discounts and AFTER applicable
  // additional charges/fees.
  //
  // TAX BASE =
  // calculated line-item subtotal
  // - calculated discount
  // + additional charges
  //
  // Partial/full payment is NEVER included in the tax base.
  // ============================================================

  let calculatedTax = null;
  let taxReconciled = null;
  let taxDifference = null;
  let taxBaseAfterDiscount = null;

  if (
    calculationBaseSubtotal !== null
  ) {

    // ==========================================================
    // TARGETED CHANGE:
    //
    // Include additional charges in the taxable base.
    //
    // Previous:
    // subtotal - discount
    //
    // New:
    // subtotal - discount + additionalCharges
    // ==========================================================

    taxBaseAfterDiscount =
      round2(
        calculationBaseSubtotal -
        discountAmount +
        additionalCharges
      );

    // Only independently calculate tax when
    // the invoice provides an identifiable tax rate.

    if (extractedTaxRate !== null) {

      calculatedTax =
        round2(
          taxBaseAfterDiscount *
          (extractedTaxRate / 100)
        );

      if (extractedTax !== null) {

        taxDifference =
          round2(
            extractedTax -
            calculatedTax
          );

        taxReconciled =
          isApproximatelyEqual(
            extractedTax,
            calculatedTax
          );

        if (!taxReconciled) {

          problems.push(
            `Calculated tax ${calculatedTax.toFixed(2)} does not match extracted tax ${extractedTax.toFixed(2)} at ${extractedTaxRate}%`
          );
        }
      }
    }
  }

  // ============================================================
  // AUTHORITATIVE TAX FOR TOTAL CALCULATION
  //
  // If a tax rate is available, use the independently
  // calculated tax.
  //
  // If no tax rate is available, preserve the previous
  // extracted-tax behavior so existing valid invoices
  // without an identifiable rate are not broken.
  // ============================================================

  let taxForCalculation = 0;

  if (calculatedTax !== null) {

    taxForCalculation = calculatedTax;

  } else if (extractedTax !== null) {

    taxForCalculation = extractedTax;
  }

  // ============================================================
  // CALCULATE EXPECTED TOTAL
  // ============================================================

  let calculatedExpectedTotal = null;

  if (calculationBaseSubtotal !== null) {

    calculatedExpectedTotal =
      round2(
        calculationBaseSubtotal -
        discountAmount +
        additionalCharges +
        taxForCalculation
      );
  }

  // ============================================================
  // TOTAL RECONCILIATION
  // ============================================================

  let totalReconciled = null;

  if (
    calculatedExpectedTotal !== null &&
    extractedTotal !== null
  ) {

    totalReconciled =
      isApproximatelyEqual(
        extractedTotal,
        calculatedExpectedTotal
      );
  }

  // ============================================================
  // PAYMENT / AMOUNT DUE RECONCILIATION
  // ============================================================

  let calculatedExpectedAmountDue = null;
  let amountDueReconciled = null;
  let paymentMathReconciled = null;
  let amountDueDifference = null;

  if (calculatedExpectedTotal !== null) {

    calculatedExpectedAmountDue =
      round2(
        Math.max(
          calculatedExpectedTotal -
          extractedPaymentReceived,
          0
        )
      );
  }

  // ============================================================
  // IMPORTANT AMOUNT-DUE HANDLING
  // ============================================================

  let effectiveAmountDue = extractedAmountDue;

  if (calculatedExpectedAmountDue !== null) {

    effectiveAmountDue =
      calculatedExpectedAmountDue;

    if (extractedAmountDue !== null) {

      amountDueDifference =
        round2(
          extractedAmountDue -
          calculatedExpectedAmountDue
        );

      amountDueReconciled =
        isApproximatelyEqual(
          extractedAmountDue,
          calculatedExpectedAmountDue
        );

      const extractedLooksLikeGrossTotal =
        extractedTotal !== null &&
        isApproximatelyEqual(
          extractedAmountDue,
          extractedTotal
        );

      if (
        !amountDueReconciled &&
        extractedPaymentReceived > 0 &&
        extractedLooksLikeGrossTotal
      ) {

        amountDueReconciled = true;
      }
    }

    paymentMathReconciled =
      isApproximatelyEqual(
        effectiveAmountDue,
        calculatedExpectedAmountDue
      );

    // ==========================================================
    // TARGETED CHANGE:
    //
    // Flag a mismatch when the amount printed on the invoice
    // does not equal the independently calculated balance after
    // payments.
    //
    // IMPORTANT:
    // - Do NOT overwrite extractedAmountDue.
    // - Do NOT change effectiveAmountDue.
    // - Do NOT alter the existing gross-total false-positive
    //   handling below.
    // - This only adds the discrepancy to the validation issues.
    // ==========================================================

    if (
      amountDueReconciled === false &&
      extractedAmountDue !== null &&
      calculatedExpectedAmountDue !== null
    ) {
      problems.push(
        `Calculated amount due ${calculatedExpectedAmountDue.toFixed(2)} does not match extracted amount due ${extractedAmountDue.toFixed(2)}`
      );
    }
  }

  // ============================================================
  // REMAINING BALANCE
  // ============================================================

  let remainingBalance = null;

  if (calculatedExpectedTotal !== null) {

    remainingBalance =
      round2(
        Math.max(
          calculatedExpectedTotal -
          extractedPaymentReceived,
          0
        )
      );
  }

  // ============================================================
  // TOTAL VS AMOUNT DUE
  // ============================================================

  let totalMatchesAmountDue = null;

  if (
    calculatedExpectedTotal !== null &&
    effectiveAmountDue !== null
  ) {

    if (extractedPaymentReceived > 0) {

      totalMatchesAmountDue =
        isApproximatelyEqual(
          calculatedExpectedTotal -
          extractedPaymentReceived,
          effectiveAmountDue
        );

    } else {

      totalMatchesAmountDue =
        isApproximatelyEqual(
          calculatedExpectedTotal,
          effectiveAmountDue
        );
    }
  }

  // ============================================================
  // TAX STATUS
  // ============================================================

  const taxPresent =
    extractedTax !== null;

  // ============================================================
  // SUSPICIOUS LINE ITEM DETECTION
  // ============================================================

  if (Array.isArray(invoice.line_items)) {

    for (const line of invoice.line_items) {

      const itemName = text(
        line?.item_name
      ).toUpperCase();

      const financialKeywords = [
        "VAT",
        "VALUE ADDED TAX",
        "LOCAL GOVT",
        "LOCAL GOVERNMENT",
        "DOCUMENTARY",
        "PREMIUM",
        "OTHERS"
      ];

      let keywordCount = 0;

      for (const keyword of financialKeywords) {

        if (itemName.includes(keyword)) {
          keywordCount++;
        }
      }

      if (keywordCount >= 2) {

        problems.push(
          "Multiple financial lines appear to have been combined into one line item"
        );

        break;
      }
    }
  }

  // ============================================================
  // REMOVE RECOVERABLE AMOUNT-DUE FALSE POSITIVE
  // ============================================================

  if (
    calculatedExpectedAmountDue !== null &&
    extractedAmountDue !== null &&
    extractedPaymentReceived > 0 &&
    extractedTotal !== null &&
    isApproximatelyEqual(
      extractedAmountDue,
      extractedTotal
    ) &&
    !isApproximatelyEqual(
      extractedAmountDue,
      calculatedExpectedAmountDue
    )
  ) {

    for (let i = problems.length - 1; i >= 0; i--) {

      if (
        problems[i].startsWith(
          "Calculated amount due "
        )
      ) {
        problems.splice(i, 1);
      }
    }
  }

  // ============================================================
  // TOTAL DISCREPANCY HANDLING
  // ============================================================

  if (
    calculatedExpectedTotal !== null &&
    extractedTotal !== null &&
    !isApproximatelyEqual(
      calculatedExpectedTotal,
      extractedTotal
    ) &&
    calculatedLineItemsTotal !== null &&
    discountAmount !== null
  ) {

    for (let i = problems.length - 1; i >= 0; i--) {

      if (
        problems[i].startsWith(
          "Calculated total "
        )
      ) {
        problems.splice(i, 1);
      }
    }
  }

  // ============================================================
  // LINE ITEM / SUBTOTAL DISCREPANCY
  // ============================================================

  if (
    calculatedLineItemsTotal !== null &&
    extractedSubtotal !== null &&
    !isApproximatelyEqual(
      calculatedLineItemsTotal,
      extractedSubtotal
    )
  ) {

    for (let i = problems.length - 1; i >= 0; i--) {

      if (
        problems[i].startsWith(
          "Calculated line items total "
        )
      ) {
        problems.splice(i, 1);
      }
    }
  }

  // ============================================================
  // FINANCIAL VALIDATION SUMMARY
  // ============================================================

  const financialValidationIssues =
    problems.filter(issue =>
      issue.includes("Calculated") ||
      issue.includes("does not match") ||
      issue.includes("Missing total")
    );

  // ============================================================
  // FINAL VALIDATION
  // ============================================================

  const valid =
    problems.length === 0;

  // ============================================================
  // OUTPUT
  // ============================================================

  output.push({
    json: {

      ...invoice,

      // --------------------------------------------------------
      // STANDARDIZED VALUES
      // --------------------------------------------------------

      currency:
        normalizedCurrency,

      // Full invoice amount BEFORE payments.
      total_amount:
        calculatedExpectedTotal !== null
          ? calculatedExpectedTotal
          : extractedTotal,

      // Remaining amount AFTER payments.
      amount_due:
        effectiveAmountDue,

      // Explicit final-balance field for downstream nodes.
      final_total_due:
        effectiveAmountDue,

      payment_received:
        extractedPaymentReceived,

      // Use calculated tax when tax rate is available.
      // Otherwise preserve extracted tax.
      tax:
        calculatedTax !== null
          ? calculatedTax
          : extractedTax,

      // --------------------------------------------------------
      // FINANCIAL VALIDATION
      // --------------------------------------------------------

      financial_validation: {

        calculated_product_service_total:
          calculatedLineItemsTotal,

        calculated_all_line_items_total:
          calculatedLineItemsTotal,

        extracted_subtotal:
          extractedSubtotal,

        calculation_base_subtotal:
          calculationBaseSubtotal,

        calculated_subtotal_after_discount:
          calculatedSubtotalAfterDiscount,

        extracted_subtotal_after_discount:
          extractedSubtotalAfterDiscount,

        subtotal_after_discount_reconciled:
          subtotalAfterDiscountReconciled,

        line_items_match_subtotal:
          lineItemsMatchSubtotal,

        // ------------------------------------------------------
        // TAX
        // ------------------------------------------------------

        tax_present:
          taxPresent,

        tax_rate_present:
          extractedTaxRate !== null,

        tax_rate:
          extractedTaxRate,

        tax_base_after_discount:
          taxBaseAfterDiscount,

        tax_amount:
          extractedTax ?? 0,

        calculated_tax:
          calculatedTax,

        extracted_tax:
          extractedTax,

        tax_difference:
          taxDifference,

        tax_reconciled:
          taxReconciled,

        tax_already_in_line_items:
          0,

        tax_not_in_line_items:
          extractedTax ?? 0,

        // ------------------------------------------------------
        // DISCOUNT
        // ------------------------------------------------------

        discount_present:
          discountPresent,

        discount_amount:
          discountAmount,

        discount_amount_source:
          discountAmountSource,

        discount_explicit_amount:
          explicitDiscountAmount,

        discount_derived_amount:
          derivedDiscountAmount,

        discount_already_in_line_items:
          0,

        discount_not_in_line_items:
          discountAmount,

        // ------------------------------------------------------
        // ADDITIONAL CHARGES
        // ------------------------------------------------------

        additional_charges:
          additionalCharges,

        charges_already_represented:
          0,

        additional_charges_not_in_line_items:
          additionalCharges,

        // ------------------------------------------------------
        // CALCULATED TOTAL
        // ------------------------------------------------------

        calculated_base_total:
          calculationBaseSubtotal !== null
            ? round2(
                calculationBaseSubtotal -
                discountAmount +
                taxForCalculation
              )
            : null,

        calculated_expected_total:
          calculatedExpectedTotal,

        effective_total_amount:
          calculatedExpectedTotal,

        extracted_total:
          extractedTotal,

        total_reconciled:
          totalReconciled,

        ai_total_reconciled:
          totalReconciled,

        // ------------------------------------------------------
        // AMOUNT DUE
        // ------------------------------------------------------

        amount_due_present:
          extractedAmountDue !== null,

        extracted_amount_due:
          extractedAmountDue,

        calculated_expected_amount_due:
          calculatedExpectedAmountDue,

        amount_due_reconciled:
          amountDueReconciled,

        total_matches_amount_due:
          totalMatchesAmountDue,

        amount_due_difference:
          amountDueDifference,

        // ------------------------------------------------------
        // PAYMENT
        // ------------------------------------------------------

        payment_received:
          extractedPaymentReceived,

        payment_math_reconciled:
          paymentMathReconciled,

        remaining_balance:
          remainingBalance,

        // ------------------------------------------------------
        // ADJUSTMENTS
        // ------------------------------------------------------

        adjustment_explains_amount_due_difference:
          amountDueReconciled === true
      },

      // --------------------------------------------------------
      // FINANCIAL VALIDATION ISSUES
      // --------------------------------------------------------

      financial_validation_issues:
        financialValidationIssues,

      // --------------------------------------------------------
      // EXTRACTION STATUS
      // --------------------------------------------------------

      extraction_valid:
        valid,

      extraction_status:
        valid
          ? "VALID"
          : "REVIEW_REQUIRED",

      extraction_issues:
        problems
    }
  });
}

return output;

