const items = $input.all();

const output = [];

for (const item of items) {
  let content = item.json.choices[0].message.content;

  // Preserve file metadata from JSON or binary input
  let fileName = item.json.file_name || null;
  let mimeType = item.json.mime_type || "application/pdf";

  // Try to get filename/mime type from binary data if not available in JSON
  if (item.binary) {
    const binaryKeys = Object.keys(item.binary);

    if (binaryKeys.length > 0) {
      const binaryData = item.binary[binaryKeys[0]];

      if (!fileName && binaryData.fileName) {
        fileName = binaryData.fileName;
      }

      if (binaryData.mimeType) {
        mimeType = binaryData.mimeType;
      }
    }
  }

  // If the AI already returned an object, use it directly
  if (typeof content === 'object') {
  output.push({
    json: {
      ...content,
      file_name: $('Route by File Type').first().json.file_name || null,
      mime_type: $('Route by File Type').first().json.mime_type || 'application/pdf'
    }
  });
  continue;
}

  // Remove Markdown code fences if the AI added them
  content = content
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  // Fix simple arithmetic expressions returned inside numeric JSON fields.
  // Example:
  // "tax": 53.76 + 2.24 + 56.00 + 39.00
  // becomes:
  // "tax": 151
  content = content.replace(
    /("[^"]+"\s*:\s*)(\d+(?:\.\d+)?(?:\s*\+\s*\d+(?:\.\d+)?)+)(?=\s*[,}])/g,
    (match, prefix, expression) => {
      const numbers = expression
        .split('+')
        .map(value => Number(value.trim()));

      const total = numbers.reduce((sum, value) => sum + value, 0);

      return prefix + total;
    }
  );

  const invoice = JSON.parse(content);

  output.push({
  json: {
    ...invoice,
    file_name: $('Route by File Type').first().json.file_name || null,
    mime_type: $('Route by File Type').first().json.mime_type || 'application/pdf'
  }
});
}

return output;

